from collections import deque


def minRemovals(grid):
    rows, cols = len(grid), len(grid[0])
    BIG = 10 ** 9
    dist = [[BIG] * cols for _ in range(rows)]
    dist[0][0] = 0
    dq = deque([(0, 0)])
    while dq:
        y, x = dq.popleft()
        d = dist[y][x]
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols:
                nd = d + grid[ny][nx]
                if nd < dist[ny][nx]:
                    dist[ny][nx] = nd
                    if grid[ny][nx] == 0:
                        dq.appendleft((ny, nx))
                    else:
                        dq.append((ny, nx))
    return dist[rows - 1][cols - 1]
